#pragma once

namespace nexus::web {

// The Nexus wordmark ("nexus/tune"), white on transparent, 251x88, embedded as a base64 PNG
// data-URI so the self-contained web pages stay dependency-free and work offline on the speaker.
// Source artwork lives at assets/nexus-logo.png; regenerate the web copy with:
//   sips --resampleHeight 88 assets/nexus-logo.png --out assets/nexus-logo-web.png
//   base64 -i assets/nexus-logo-web.png | tr -d '\n'
inline const char* nexusLogoDataUri() {
  return "data:image/png;base64,";
}

}  // namespace nexus::web
